/// What a kept read reaches of this device: `Device.isOnline` as [connectivity] follows it, the
/// device [store] its copies live in, and the device's clock.
class DeviceKept implements KeptDevice {
  DeviceKept(this._connectivity, this._store);

  final DeviceConnectivity _connectivity;
  final DeviceStore _store;

  @override
  bool get isOnline => _connectivity.isOnline;

  @override
  int get nowMs => DateTime.now().millisecondsSinceEpoch;

  @override
  Future<String?> get(String key) => _store.get(key);

  @override
  Future<void> put(String key, String bytes) => _store.put(key, bytes);

  @override
  void reportUnreachable() => _connectivity.reportUnreachable();

  @override
  void addListener(VoidCallback listener) => _connectivity.addListener(listener);

  @override
  void removeListener(VoidCallback listener) => _connectivity.removeListener(listener);
}
